INSERT INTO "app"."StandardCategory" ("id", "slug", "name", "description", "isCore", "sortOrder") VALUES
  ('a1000000-0000-0000-0000-000000000001', 'broadband-internet', 'Broadband Internet', 'Get the right connection type and speed, and a backup connection to ensure resilience.', true, 1),
  ('a1000000-0000-0000-0000-000000000002', 'cyber-security', 'Cyber Security', 'Keep your school cyber secure and control and secure user accounts.', true, 2),
  ('a1000000-0000-0000-0000-000000000003', 'digital-leadership-governance', 'Digital Leadership & Governance', 'Effective digital technology leadership, governance, roles and processes.', true, 3),
  ('a1000000-0000-0000-0000-000000000004', 'filtering-monitoring', 'Filtering & Monitoring', 'Provide a safe online environment with appropriate filtering and monitoring systems.', true, 4),
  ('a1000000-0000-0000-0000-000000000005', 'network-switching', 'Network Switching', 'Proper network switches and switching infrastructure for reliability, security and resilience.', true, 5),
  ('a1000000-0000-0000-0000-000000000006', 'wireless-network', 'Wireless Network', 'Latest wireless network standards for performance, coverage, management and security.', true, 6),
  ('a1000000-0000-0000-0000-000000000007', 'cloud-solutions', 'Cloud Solutions', 'Use or move to cloud solutions, managing access, availability, data protection and backup.', false, 7),
  ('a1000000-0000-0000-0000-000000000008', 'digital-accessibility', 'Digital Accessibility', 'Digital products, content and services accessible and usable for all.', false, 8),
  ('a1000000-0000-0000-0000-000000000009', 'it-support', 'IT Support', 'Plan, commission and review IT support services for suitable digital technology support.', false, 9),
  ('a1000000-0000-0000-0000-000000000010', 'devices', 'Devices (Laptops, Desktops & Tablets)', 'Get the right digital devices for teaching and learning.', false, 10),
  ('a1000000-0000-0000-0000-000000000011', 'network-cabling', 'Network Cabling', 'Right copper cabling, optical fibre and installation standards.', false, 11),
  ('a1000000-0000-0000-0000-000000000012', 'servers-storage', 'Servers & Storage', 'Right servers and storage, including security, energy efficiency and environments.', false, 12)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0001-000000000001', 'a1000000-0000-0000-0000-000000000001', 'broadband-full-fibre', 'Full fibre broadband connection', 'Primary schools: min 100Mbps down / 30Mbps up. Secondary/FE: capacity for 1Gbps symmetric.', '1: No fibre; relying on copper ADSL. 2: Part-fibre (FTTC). 3: Full fibre ordered/installed but not optimised. 4: Full fibre active, meeting DfE speed targets. 5: Leased line with SLA, exceeding targets.', 1),
  ('b1000000-0000-0000-0001-000000000002', 'a1000000-0000-0000-0000-000000000001', 'broadband-backup-connection', 'Backup broadband connection for resilience', 'Multiple broadband services of different types with automatic failover.', '1: No backup. 2: Manual failover (e.g. 4G dongle). 3: Secondary connection, manual switchover. 4: Automatic failover with different service types. 5: Fully redundant with diverse routes and tested DR.', 2)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0002-000000000001', 'a1000000-0000-0000-0000-000000000002', 'cyber-risk-assessment', 'Conduct a cyber risk assessment annually', 'Annual risk assessment reviewed every term, covering all digital technology.', '1: No risk assessment. 2: Informal awareness of risks. 3: Initial assessment done but not reviewed. 4: Annual assessment with termly reviews. 5: Continuous risk management with board reporting.', 1),
  ('b1000000-0000-0000-0002-000000000002', 'a1000000-0000-0000-0000-000000000002', 'cyber-antimalware-firewall', 'Anti-malware and firewall protection', 'All devices protected with up-to-date anti-malware and properly configured firewalls.', '1: No or expired protection. 2: Partial coverage, not centrally managed. 3: All devices covered but updates inconsistent. 4: Centrally managed, auto-updating protection on all devices. 5: EDR/XDR with SOC monitoring and incident response.', 2),
  ('b1000000-0000-0000-0002-000000000003', 'a1000000-0000-0000-0000-000000000002', 'cyber-user-accounts', 'Secure user account management', 'Controlled account creation/removal, MFA for staff, least-privilege access.', '1: Shared accounts, no process. 2: Individual accounts but no MFA. 3: MFA for admins, joiners/leavers process exists. 4: MFA for all staff, automated provisioning, regular access reviews. 5: Zero-trust architecture, continuous authentication.', 3),
  ('b1000000-0000-0000-0002-000000000004', 'a1000000-0000-0000-0000-000000000002', 'cyber-backup-plan', 'Data backup plan reviewed annually', '3-2-1 backup rule for critical data, tested restores, documented plan.', '1: No backups. 2: Ad-hoc backups, never tested. 3: Regular backups but no offsite or testing. 4: 3-2-1 backups with annual restore testing. 5: Immutable backups, automated testing, <4h RTO.', 4),
  ('b1000000-0000-0000-0002-000000000005', 'a1000000-0000-0000-0000-000000000002', 'cyber-incident-response', 'Cyber incident response plan', 'Documented plan with roles, tested annually, aligned to NCSC guidance.', '1: No plan. 2: Informal understanding of what to do. 3: Written plan but untested. 4: Tested plan with defined roles and communication. 5: Regular tabletop exercises, links to NCSC, insurance in place.', 5)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0003-000000000001', 'a1000000-0000-0000-0000-000000000003', 'governance-slt-digital-lead', 'SLT member responsible for digital technology', 'A named SLT member accountable for digital strategy and standards.', '1: No ownership assigned. 2: Informally handled by IT support. 3: Named SLT lead but limited engagement. 4: Active SLT lead with clear remit and governor link. 5: Digital lead embedded in SLT decisions, governor champion appointed.', 1),
  ('b1000000-0000-0000-0003-000000000002', 'a1000000-0000-0000-0000-000000000003', 'governance-registers', 'Up-to-date asset, contract and information registers', 'Contracts register, asset register, and information asset register maintained.', '1: No registers. 2: Partial/outdated records. 3: Registers exist but not routinely updated. 4: All registers current, reviewed before financial planning. 5: Automated asset discovery, live dashboards, proactive renewal management.', 2),
  ('b1000000-0000-0000-0003-000000000003', 'a1000000-0000-0000-0000-000000000003', 'governance-disaster-recovery', 'Disaster recovery and business continuity plans', 'DR and BC plans covering digital technology, tested annually.', '1: No plans. 2: General BC plan without digital specifics. 3: Digital DR plan exists but untested. 4: Tested annually, hard copies available, staff briefed. 5: Regular simulation exercises, suppliers integrated, continuous improvement.', 3),
  ('b1000000-0000-0000-0003-000000000004', 'a1000000-0000-0000-0000-000000000003', 'governance-digital-strategy', 'Digital technology strategy reviewed annually', 'Strategy aligned to school development plan, reviewed yearly with stakeholder input.', '1: No strategy. 2: Informal plans driven by IT support. 3: Written strategy but not reviewed. 4: Annual review with SLT, curriculum and finance input. 5: Living strategy with clear KPIs, governor oversight, evidence of impact.', 4)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0004-000000000001', 'a1000000-0000-0000-0000-000000000004', 'filtering-roles-responsibilities', 'Clear roles and responsibilities for filtering & monitoring', 'SLT, DSL and IT support roles documented with accountability for filtering/monitoring.', '1: No defined roles. 2: IT handles it alone informally. 3: Roles documented but DSL not actively involved. 4: Clear accountability across SLT/DSL/IT, staff trained. 5: Regular cross-functional reviews, governor oversight.', 1),
  ('b1000000-0000-0000-0004-000000000002', 'a1000000-0000-0000-0000-000000000004', 'filtering-annual-review', 'Annual review of filtering and monitoring provision', 'Yearly review considering student risk profile, system capabilities and policy alignment.', '1: Never reviewed. 2: Only after incidents. 3: Informal annual check. 4: Formal annual review with documented outcomes and actions. 5: Continuous review cycle, informed by data, feeding into strategy.', 2),
  ('b1000000-0000-0000-0004-000000000003', 'a1000000-0000-0000-0000-000000000004', 'filtering-harmful-content', 'Filtering blocks harmful and inappropriate content', 'IWF and CTIRU blocklists active; age-appropriate profiles; covers all devices.', '1: No filtering. 2: Basic filtering, not all devices covered. 3: Filtering on school network only, not BYOD/off-site. 4: All devices covered, IWF/CTIRU active, profiles by user type. 5: Real-time content analysis, VPN/proxy blocking, regular testing.', 3),
  ('b1000000-0000-0000-0004-000000000004', 'a1000000-0000-0000-0000-000000000004', 'filtering-monitoring-strategies', 'Effective monitoring strategies', 'Technical and manual monitoring proportionate to risk, with alert/reporting processes.', '1: No monitoring. 2: Manual only (teacher observation). 3: Technical monitoring on some devices. 4: Comprehensive monitoring, alerts to DSL, documented responses. 5: AI-enhanced monitoring, proactive intervention, trend analysis.', 4)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0005-000000000001', 'a1000000-0000-0000-0000-000000000005', 'switching-performance', 'Network switches meet performance requirements', 'Managed switches with adequate port speeds, PoE for access points, VLAN support.', '1: Unmanaged/consumer switches. 2: Mix of managed and unmanaged. 3: All managed but aging/under-spec. 4: Enterprise-grade, adequate PoE budget, VLAN-configured. 5: Latest generation with full redundancy, monitoring and capacity headroom.', 1),
  ('b1000000-0000-0000-0005-000000000002', 'a1000000-0000-0000-0000-000000000005', 'switching-resilience', 'Network resilience and redundancy', 'Redundant uplinks, UPS protection, and failover for critical paths.', '1: Single points of failure throughout. 2: UPS on core only. 3: Some redundancy in core, edge is single-path. 4: Redundant core, UPS on all comms rooms, monitoring. 5: Full mesh/ring topology, automatic failover, regular testing.', 2)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0006-000000000001', 'a1000000-0000-0000-0000-000000000006', 'wireless-performance', 'Wi-Fi performance meets educational needs', 'Latest Wi-Fi standard (Wi-Fi 7 / 802.11be), supporting concurrent use of all devices.', '1: Wi-Fi 4 or older, frequent dropouts. 2: Wi-Fi 5, insufficient capacity. 3: Wi-Fi 6, adequate for current use. 4: Wi-Fi 6E/7, designed for full device load. 5: Wi-Fi 7 with capacity planning, QoS and future-proofing.', 1),
  ('b1000000-0000-0000-0006-000000000002', 'a1000000-0000-0000-0000-000000000006', 'wireless-coverage', 'Full coverage across all learning spaces', 'Access points in all classrooms, with higher-spec units in halls/large spaces.', '1: Patchy coverage, many dead spots. 2: Coverage in main areas only. 3: Most classrooms covered, some gaps. 4: Full site coverage validated by heat mapping. 5: Continuous monitoring, automatic AP steering, 100% coverage.', 2),
  ('b1000000-0000-0000-0006-000000000003', 'a1000000-0000-0000-0000-000000000006', 'wireless-management', 'Central wireless management and monitoring', 'Cloud or on-prem controller for configuration, firmware updates and alerting.', '1: Standalone APs, no central management. 2: Basic management, manual updates. 3: Central controller, some automation. 4: Cloud-managed, auto firmware updates, alerting. 5: AI-optimised, predictive maintenance, full visibility.', 3),
  ('b1000000-0000-0000-0006-000000000004', 'a1000000-0000-0000-0000-000000000006', 'wireless-security', 'Wireless network security', 'WPA3, certificate-based auth, network segregation, guest isolation.', '1: Open or WPA2-Personal. 2: WPA2-Enterprise but shared credentials. 3: WPA2/3-Enterprise with individual auth. 4: WPA3, VLANs, certificate auth, guest isolation. 5: Zero-trust wireless, WIPS, MFA for admin, regular pen testing.', 4)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0007-000000000001', 'a1000000-0000-0000-0000-000000000007', 'cloud-migration', 'Migration from on-premise to cloud', 'Assessment of services suitable for cloud; progressive migration where beneficial.', '1: All on-premise, no cloud strategy. 2: Some SaaS (e.g. email) but ad-hoc. 3: Assessment done, migration plan in place. 4: Majority cloud, hybrid only where justified. 5: Cloud-first policy, optimised costs, minimal on-prem.', 1),
  ('b1000000-0000-0000-0007-000000000002', 'a1000000-0000-0000-0000-000000000007', 'cloud-data-protection', 'Cloud data protection and GDPR compliance', 'DPIAs done, data residency in UK/EU, sharing agreements in place.', '1: No awareness of cloud data risks. 2: Some awareness but no DPIAs. 3: DPIAs for key systems, gaps in others. 4: All cloud systems assessed, compliant agreements. 5: Continuous compliance monitoring, automated data governance.', 2),
  ('b1000000-0000-0000-0007-000000000003', 'a1000000-0000-0000-0000-000000000007', 'cloud-id-management', 'Central ID and access management', 'Single sign-on for all cloud services, documented joiners/leavers process.', '1: Multiple separate logins per user. 2: SSO for some systems. 3: SSO for most, joiners/leavers partially automated. 4: Full SSO, automated provisioning/deprovisioning. 5: Conditional access policies, real-time risk-based auth.', 3),
  ('b1000000-0000-0000-0007-000000000004', 'a1000000-0000-0000-0000-000000000007', 'cloud-backup', 'Cloud data backup provision', 'Backup needs assessed per solution; critical data follows 3-2-1 rule.', '1: Relying solely on provider defaults. 2: Aware of backup gaps, no action. 3: Third-party backup for critical data. 4: All cloud data backup assessed and provisioned. 5: Automated backup verification, tested recovery, documented RTOs.', 4)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0008-000000000001', 'a1000000-0000-0000-0000-000000000008', 'accessibility-awareness', 'Accessibility awareness and policy', 'Staff understand accessibility requirements; policy in place for digital content.', '1: No awareness. 2: Some staff aware, no policy. 3: Policy exists, limited implementation. 4: Policy embedded, training provided, content audited. 5: Proactive inclusion, user testing with diverse users, WCAG 2.2 AA.', 1),
  ('b1000000-0000-0000-0008-000000000002', 'a1000000-0000-0000-0000-000000000008', 'accessibility-assistive-tech', 'Assistive technology provision', 'Appropriate assistive technology available for students with SEND.', '1: No provision. 2: Reactive provision on request. 3: Some standard tools available. 4: Needs-assessed provision, staff trained to support. 5: Comprehensive provision, integrated into teaching, regularly reviewed.', 2)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0009-000000000001', 'a1000000-0000-0000-0000-000000000009', 'it-support-meeting-standards', 'IT support helps meet digital standards', 'Support team understands and actively works towards DfE standards.', '1: Unaware of standards. 2: Aware but no structured approach. 3: Standards referenced in support planning. 4: Active progress tracking against standards. 5: Support SLA linked to standards compliance, continuous improvement.', 1),
  ('b1000000-0000-0000-0009-000000000002', 'a1000000-0000-0000-0000-000000000009', 'it-support-responsiveness', 'IT support responsiveness and service levels', 'Clear SLAs, priority system, recorded tickets, regular review.', '1: No SLA, ad-hoc response. 2: Informal expectations, no tracking. 3: Basic ticket system, response targets set. 4: Full helpdesk with SLAs, reporting, escalation paths. 5: Proactive monitoring, self-service options, user satisfaction tracked.', 2),
  ('b1000000-0000-0000-0009-000000000003', 'a1000000-0000-0000-0000-000000000009', 'it-support-annual-review', 'Annual IT support review', 'Yearly review of support effectiveness, capacity, skills and value for money.', '1: Never reviewed. 2: Only when problems arise. 3: Informal annual discussion. 4: Structured annual review with documented outcomes. 5: Data-driven review with benchmarking, feeds into strategy.', 3)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0010-000000000001', 'a1000000-0000-0000-0000-000000000010', 'devices-educational-needs', 'Devices meet educational needs', 'Device fleet aligned to curriculum requirements and digital strategy.', '1: Outdated/insufficient devices. 2: Some modern devices, gaps in provision. 3: Devices adequate but not strategically planned. 4: Fleet aligned to strategy, lifecycle planned, meets curriculum needs. 5: 1:1 or optimal ratio, choice of form factor, futureproofed.', 1),
  ('b1000000-0000-0000-0010-000000000002', 'a1000000-0000-0000-0000-000000000010', 'devices-management', 'Device management and security', 'MDM/endpoint management, patching, encryption, BYOD policy.', '1: Unmanaged devices. 2: Partial management (some enrolled). 3: MDM for school devices, no BYOD policy. 4: Full MDM, auto-patching, encryption, BYOD managed. 5: Zero-touch deployment, conditional access, remote wipe capability.', 2),
  ('b1000000-0000-0000-0010-000000000003', 'a1000000-0000-0000-0000-000000000010', 'devices-sustainability', 'Sustainable procurement and disposal', 'Energy-efficient devices, sustainable purchasing, secure disposal.', '1: No consideration of sustainability. 2: Some recycling, no policy. 3: Disposal process documented, some green purchasing. 4: WEEE-compliant disposal, EPEAT-rated procurement, lifecycle costing. 5: Circular economy approach, carbon-tracked, social value considered.', 3)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0011-000000000001', 'a1000000-0000-0000-0000-000000000011', 'cabling-copper-standard', 'Copper cabling meets current standards', 'Cat6/6A minimum, properly installed, tested and documented.', '1: Cat5 or unknown cabling. 2: Mix of standards, some Cat5e. 3: Mostly Cat5e/6, some documentation. 4: Cat6A throughout, certified installation, full documentation. 5: Cat6A/Cat7, future-proofed for 10GbE, labelled and maintained.', 1),
  ('b1000000-0000-0000-0011-000000000002', 'a1000000-0000-0000-0000-000000000011', 'cabling-fibre-backbone', 'Fibre backbone between buildings/floors', 'Single-mode or multi-mode fibre linking distribution points.', '1: Copper-only backbone. 2: Some fibre but aging/single-mode only in parts. 3: Fibre backbone installed, adequate capacity. 4: Multi-mode/single-mode as appropriate, redundant paths. 5: High-count fibre with spare capacity, future 40/100G ready.', 2)
INSERT INTO "app"."StandardCriterion" ("id", "categoryId", "slug", "title", "description", "guidance", "sortOrder") VALUES
  ('b1000000-0000-0000-0012-000000000001', 'a1000000-0000-0000-0000-000000000012', 'servers-security-compliance', 'Server security and data protection compliance', 'Servers patched, access-controlled, encrypted, GDPR-compliant.', '1: Unpatched, shared admin passwords. 2: Some patching, basic access control. 3: Regular patching, individual admin accounts. 4: Automated patching, encrypted at rest, access logged. 5: Hardened, monitored, pen-tested, compliance certified.', 1),
  ('b1000000-0000-0000-0012-000000000002', 'a1000000-0000-0000-0000-000000000012', 'servers-environment', 'Appropriate physical server environment', 'Dedicated server room/cabinet with cooling, power protection and access control.', '1: Under a desk / in an open area. 2: Locked cupboard, no climate control. 3: Dedicated room, basic cooling. 4: Purpose-built with UPS, cooling, fire suppression, access control. 5: Data-centre grade or fully migrated to cloud.', 2),
  ('b1000000-0000-0000-0012-000000000003', 'a1000000-0000-0000-0000-000000000012', 'servers-energy-efficiency', 'Energy-efficient and sustainable servers', 'Right-sized, virtualised where possible, energy monitoring.', '1: Old hardware, no virtualisation. 2: Some virtualisation, oversized hardware. 3: Mostly virtualised, lifecycle planned. 4: Right-sized, energy-monitored, replacement cycle. 5: Cloud-first, remaining on-prem fully optimised, carbon-tracked.', 3)
